/* catalog-social.js: the Facebook and Instagram QR codes printed on the Back
   Cover of Catalog Maker (catalog_maker.html › generateBackHTML).
   They are fb.png and insta.png from this folder, written here as data URLs
   for the same reason as catalog-logo.js: html2canvas would refuse a local
   file when the page is opened as file://, and the PDF export would fail.
   To change a QR code: replace the PNG and regenerate this file from it
   (PNG -> base64), keeping the variable names. */
window.SARV_FB_QR = 'data:image/png;base64,';
window.SARV_INSTA_QR = 'data:image/png;base64,';